-- ================================================================
-- OBGYN Integration Migration - Schema Native
-- Regenerated against actual remote schema
-- ================================================================

BEGIN;

-- ================================================================
-- PRECONDITIONS
-- ================================================================

DO $$
DECLARE
  obgyn_area_count INT;
  obgyn_topic_count INT;
  migration_c_applied BOOLEAN;
  source_validated_count INT;
BEGIN
  -- Check Migration C applied
  SELECT EXISTS (
    SELECT 1 FROM supabase_migrations.schema_migrations 
    WHERE version = '20260910174000'
  ) INTO migration_c_applied;
  
  IF NOT migration_c_applied THEN
    RAISE EXCEPTION 'Migration C (20260910174000) not applied';
  END IF;
  
  -- Check OBGYN area exists exactly once
  SELECT COUNT(*) INTO obgyn_area_count
  FROM areas WHERE code = 'OBGYN';
  
  IF obgyn_area_count != 1 THEN
    RAISE EXCEPTION 'Expected exactly 1 OBGYN area, found %', obgyn_area_count;
  END IF;
  
  -- Check no OBGYN topics exist
  SELECT COUNT(*) INTO obgyn_topic_count
  FROM topics WHERE code LIKE 'OBGYN%';
  
  IF obgyn_topic_count > 0 THEN
    RAISE EXCEPTION 'OBGYN topics already exist (%)' , obgyn_topic_count;
  END IF;
  
  -- Check 52 SOURCE_VALIDATED lessons exist
  SELECT COUNT(*) INTO source_validated_count
  FROM lessons WHERE status = 'SOURCE_VALIDATED';
  
  IF source_validated_count != 52 THEN
    RAISE EXCEPTION 'Expected 52 SOURCE_VALIDATED lessons, found %', source_validated_count;
  END IF;
  
  RAISE NOTICE 'Preconditions PASS';
END $$;

