-- ================================================================
-- POSTCONDITIONS
-- ================================================================

DO $$
DECLARE
  obgyn_topics_count INT;
  obgyn_lessons_count INT;
  obgyn_sections_count INT;
  obgyn_lesson_sources_count INT;
  review_lessons_count INT;
BEGIN
  -- Count OBGYN topics
  SELECT COUNT(*) INTO obgyn_topics_count
  FROM topics WHERE code LIKE 'OBGYN%';
  
  IF obgyn_topics_count != 3 THEN
    RAISE EXCEPTION 'Expected 3 OBGYN topics, found %', obgyn_topics_count;
  END IF;
  
  -- Count OBGYN lessons
  SELECT COUNT(*) INTO obgyn_lessons_count
  FROM lessons l
  JOIN topics t ON t.id = l.topic_id
  WHERE t.code LIKE 'OBGYN%';
  
  IF obgyn_lessons_count != 3 THEN
    RAISE EXCEPTION 'Expected 3 OBGYN lessons, found %', obgyn_lessons_count;
  END IF;
  
  -- Count OBGYN sections
  SELECT COUNT(*) INTO obgyn_sections_count
  FROM lesson_sections ls
  JOIN lessons l ON l.id = ls.lesson_id
  JOIN topics t ON t.id = l.topic_id
  WHERE t.code LIKE 'OBGYN%';
  
  IF obgyn_sections_count != 143 THEN
    RAISE EXCEPTION 'Expected 143 OBGYN sections, found %', obgyn_sections_count;
  END IF;
  
  -- Count OBGYN lesson_sources
  SELECT COUNT(*) INTO obgyn_lesson_sources_count
  FROM lesson_sources lsrc
  JOIN lessons l ON l.id = lsrc.lesson_id
  JOIN topics t ON t.id = l.topic_id
  WHERE t.code LIKE 'OBGYN%';
  
  IF obgyn_lesson_sources_count != 39 THEN
    RAISE EXCEPTION 'Expected 39 OBGYN lesson_sources, found %', obgyn_lesson_sources_count;
  END IF;
  
  -- Check all OBGYN lessons are REVIEW
  SELECT COUNT(*) INTO review_lessons_count
  FROM lessons l
  JOIN topics t ON t.id = l.topic_id
  WHERE t.code LIKE 'OBGYN%'
    AND l.status = 'REVIEW';
  
  IF review_lessons_count != 3 THEN
    RAISE EXCEPTION 'Expected 3 REVIEW OBGYN lessons, found %', review_lessons_count;
  END IF;
  
  -- Check 52 SOURCE_VALIDATED lessons still exist
  SELECT COUNT(*) INTO review_lessons_count
  FROM lessons WHERE status = 'SOURCE_VALIDATED';
  
  IF review_lessons_count != 52 THEN
    RAISE EXCEPTION 'Expected 52 SOURCE_VALIDATED lessons preserved, found %', review_lessons_count;
  END IF;
  
  RAISE NOTICE 'Postconditions PASS';
  RAISE NOTICE 'OBGYN integration complete: 3 topics, 3 lessons (REVIEW), 143 sections, % lesson_sources', obgyn_lesson_sources_count;
END $$;

COMMIT;

